mapper.select:
SELECT EXISTS(
    SELECT 1
    FROM post_like
    WHERE post_id = #{postId}
      AND user_id = #{userId}
)

mapper.delete:
DELETE FROM post_like
WHERE post_id = #{postId}
  AND user_id = #{userId}

mapper.select:
SELECT EXISTS(
    SELECT 1
    FROM post_favorite
    WHERE post_id = #{postId}
      AND user_id = #{userId}
)

mapper.delete:
DELETE FROM post_favorite
WHERE post_id = #{postId}
  AND user_id = #{userId}

DELETE FROM post_comment
WHERE post_id = #{postId}
  AND id = #{commentId}
  AND author_id = #{authorId}

mapper.update:
UPDATE post_draft
SET content_json = #{contentJson},
    schema_version = #{schemaVersion},
    version = version + 1,
    updated_by = #{updatedBy}
WHERE post_id = #{postId}
  AND version = #{expectedVersion}

UPDATE post
SET updated_at = CURRENT_TIMESTAMP(6)
WHERE id = #{postId}
  AND owner_id = #{ownerId}

UPDATE post
SET title = #{title},
    description = #{description},
    updated_at = CURRENT_TIMESTAMP(6)
WHERE id = #{postId}
  AND owner_id = #{ownerId}

UPDATE post
SET published_revision_id = NULL
WHERE id = #{postId}
  AND owner_id = #{ownerId}

mapper.delete:
DELETE FROM post
WHERE id = #{postId}
  AND owner_id = #{ownerId}
